import { Fragment, useEffect, useMemo, useState, type ReactNode } from "react";
import { useNavigate, useSearchParams } from "react-router-dom";
import { api } from "../api.js";
import { AiPlanningScreen } from "./ui.js";

type JsonMap = Record<string, unknown>;
type Recommendation = {
  type: string; title: string; score: number; buyerStage: "awareness" | "consideration" | "decision"; signal: string; why: string; expectedOutcome: string;
  newKeywordAngle?: string | null; differenceFromPrevious?: string | null;
  researchRunId?: string; recommendationSet?: "current" | "previous"; researchCreatedAt?: string;
  estimatedImpact: { low: number; high: number; metric: string; confidence: "directional" | "medium"; label: string; disclaimer: string };
  evidence: string[]; actionLabel: string;
};
type ResearchObjective = { objective: string; desiredAction: string; preferredFormat?: string | null; successDefinition?: string | null; notes?: string | null };
type ResearchFindings = {
  objectiveSummary: string; audienceNeeds: string[]; keywordInsights: string[]; geographicInsights: string[];
  siteInsights: string[]; opportunityGaps: string[]; recommendedStrategy: string; researchLimits: string[];
};
type ResearchResponse = {
  recommendations: Recommendation[];
  research: ResearchFindings | null;
  followUpQuestions: Array<{ question: string; why: string; suggestedAnswer?: string | null }>;
  evidence: { businessIntake?: JsonMap; geography?: JsonMap; keywords?: JsonMap; siteAnalysis?: JsonMap; selectedOpportunity?: JsonMap; strategyAndSeoPlan?: JsonMap; liveRefreshDiscovery?: JsonMap } | null;
  researchRun: { id: string; createdAt: string; objective: ResearchObjective } | null;
};
type Connection = { id: string; provider: string; status: string; listName: string | null; listId: string | null; credentialHint: string | null; lastVerifiedAt: string | null; errorMessage: string | null };
type Funnel = {
  id: string; seriesId: string; version: number; status: string; title: string; magnetType: string; recommendationScore: number | null; recommendationReason: string | null;
  conversionTarget: number;
  audience: string | null; primaryGoal: string | null; brandVoice: string | null; assetJson: JsonMap; landingPageJson: JsonMap; optInFormJson: JsonMap;
  thankYouPageJson: JsonMap; deliveryEmailJson: JsonMap; followUpSequenceJson: unknown[]; abTestsJson: unknown[]; seoMetadataJson: JsonMap;
  trackingPlanJson: unknown[]; validationJson: JsonMap; publicUrl: string | null; sharedWithClient: boolean; approvedAt: string | null; publishedAt: string | null;
  espConnection: Connection | null; decisions: Array<{ id: string; decision: string; comments: string | null; createdAt: string }>;
  performance: { views: number; optIns: number; downloads: number; emailsDelivered: number; emailOpens: number; emailClicks: number; conversionRate: number; openRate: number; clickRate: number };
  optimizationRecommendations: Array<{ priority: string; title: string; why: string; action: string }>;
};
type Activity = { id: string; action: string; createdAt: string; actor: { name: string | null; email: string } | null };
type Response = {
  project: { id: string; name: string; businessName: string; clientName: string | null; websiteName: string | null };
  context: { workspaceId: string; workspaceName: string; workspaceType: string; clientId: string | null; clientName: string | null; projectId: string; projectName: string; businessName: string; websiteId: string | null; websiteName: string | null };
  websiteHandoff: { siteArchitectReady: boolean; buildId: string | null; buildName: string | null; activeJob: { id: string; status: string; stage: string; progress: number; updatedAt: string } | null };
  funnels: Funnel[]; current: Funnel | null; connections: Connection[]; activities: Activity[];
  capabilities: { canGenerate: boolean; canEdit: boolean; canApprove: boolean; canManageIntegration: boolean; canPublish: boolean; readOnly: boolean; clientViewer: boolean };
};

const tabs = ["Funnel assets", "Landing & form", "Email sequence", "Export & handoff", "Integration", "Performance", "History"] as const;
type LandingContentMode = "sales_pitch" | "full_content";
const supportedTypes = ["Checklist", "Guide", "Comparison", "Buyer's Guide", "Mini eBook (1,000–2,000 words)", "eBook", "PDF Report", "Template", "Worksheet", "Cheat Sheet", "Email Course", "Toolkit", "Resource List", "Case Study", "Free Trial", "Coupon or Discount", "Quiz", "Calculator"];
const object = (value: unknown): JsonMap => value && typeof value === "object" && !Array.isArray(value) ? value as JsonMap : {};
const list = (value: unknown) => Array.isArray(value) ? value : [];
const text = (value: unknown, fallback = "Not generated") => typeof value === "string" && value.trim() ? value : fallback;
const label = (value: string) => value.replace(/_/g, " ").replace(/\b\w/g, (char) => char.toUpperCase());
const date = (value: string | null) => value ? new Date(value).toLocaleString() : "Not yet";
const statusTone = (status: string) => status === "published" || status === "approved" || status === "connected" ? "bg-emerald-100 text-emerald-800" : status === "failed" || status === "changes_requested" ? "bg-rose-100 text-rose-800" : "bg-amber-100 text-amber-800";

export default function LeadFunnelWorkspace({ projectId, suggestedIdeas, startRequestKey = 0 }: { projectId: string; suggestedIdeas: string[]; startRequestKey?: number }) {
  const navigate = useNavigate();
  const [searchParams] = useSearchParams();
  const [data, setData] = useState<Response | null>(null);
  const [researchData, setResearchData] = useState<ResearchResponse>({ recommendations: [], research: null, followUpQuestions: [], evidence: null, researchRun: null });
  const [recommendations, setRecommendations] = useState<Recommendation[]>([]);
  const [activeId, setActiveId] = useState<string | null>(null);
  const [tab, setTab] = useState<(typeof tabs)[number]>(tabs[0]);
  const [selectedIdea, setSelectedIdea] = useState("");
  const [selectedResearchRunId, setSelectedResearchRunId] = useState<string | null>(null);
  const [customType, setCustomType] = useState("");
  const [instructions, setInstructions] = useState("");
  const [objective, setObjective] = useState("");
  const [desiredAction, setDesiredAction] = useState("generate_qualified_leads");
  const [successDefinition, setSuccessDefinition] = useState("");
  const [busy, setBusy] = useState("");
  const [autoResearchAttempted, setAutoResearchAttempted] = useState(false);
  const [setupStep, setSetupStep] = useState<0 | 1 | 2 | 3 | 4>(0);
  const [generationAudience, setGenerationAudience] = useState("");
  const [generationCta, setGenerationCta] = useState("");
  const [generationDetails, setGenerationDetails] = useState("");
  const [targetWordCount, setTargetWordCount] = useState("");
  const [generationVisuals, setGenerationVisuals] = useState({ charts: true, images: true, diagrams: true });
  const [generationFunnelSetup, setGenerationFunnelSetup] = useState({ contentMode: "sales_pitch" as LandingContentMode, leadMagnetTitle: "", landingHeadline: "", landingDescription: "", ctaText: "", deliveryEmailSubject: "", deliveryEmailContent: "", conversionTarget: "5" });
  const [generationSeriesId, setGenerationSeriesId] = useState<string | null>(null);
  const [notice, setNotice] = useState<{ tone: "success" | "error" | "info"; text: string } | null>(null);
  const [providerName, setProviderName] = useState("");
  const [providerEmbedCode, setProviderEmbedCode] = useState("");
  const [metrics, setMetrics] = useState({ views: "", optIns: "", downloads: "", emailsDelivered: "", emailOpens: "", emailClicks: "" });
  const [websiteHandoffOpen, setWebsiteHandoffOpen] = useState(false);
  const [websiteHandoff, setWebsiteHandoff] = useState({ title: "", slug: "", primaryKeyword: "", targetCta: "Get the resource", includeInNavigation: false });

  const load = async (preferNewestRecommendation = false) => {
    const [workspace, ideas] = await Promise.all([
      api.get<Response>(`/api/projects/${projectId}/lead-magnets`),
      api.get<ResearchResponse>(`/api/projects/${projectId}/lead-magnets/recommendations`),
    ]);
    setData(workspace); setResearchData(ideas); setRecommendations(ideas.recommendations);
    if (ideas.researchRun?.objective) {
      setObjective(ideas.researchRun.objective.objective);
      setDesiredAction(ideas.researchRun.objective.desiredAction);
      setCustomType(ideas.researchRun.objective.preferredFormat ?? "");
      setSuccessDefinition(ideas.researchRun.objective.successDefinition ?? "");
      setInstructions(ideas.researchRun.objective.notes ?? "");
    }
    setActiveId((current) => current && workspace.funnels.some((item) => item.id === current) ? current : workspace.current?.id ?? null);
    const retainedSelection = preferNewestRecommendation ? ideas.recommendations[0] : ideas.recommendations.find((item) => item.title === selectedIdea && item.researchRunId === selectedResearchRunId) ?? ideas.recommendations[0];
    setSelectedIdea(retainedSelection?.title ?? "");
    setSelectedResearchRunId(retainedSelection?.researchRunId ?? null);
  };
  useEffect(() => { setData(null); setNotice(null); setObjective(""); setSuccessDefinition(""); setInstructions(""); setSetupStep(0); setGenerationAudience(""); setGenerationCta(""); setGenerationDetails(""); setTargetWordCount(""); setGenerationVisuals({ charts: true, images: true, diagrams: true }); setGenerationFunnelSetup({ contentMode: "sales_pitch", leadMagnetTitle: "", landingHeadline: "", landingDescription: "", ctaText: "", deliveryEmailSubject: "", deliveryEmailContent: "", conversionTarget: "5" }); setGenerationSeriesId(null); setSelectedResearchRunId(null); setAutoResearchAttempted(false); setResearchData({ recommendations: [], research: null, followUpQuestions: [], evidence: null, researchRun: null }); void load().catch((error) => setNotice({ tone: "error", text: error instanceof Error ? error.message : "Could not load lead funnels." })); }, [projectId]);
  const funnel = useMemo(() => data?.funnels.find((item) => item.id === activeId) ?? data?.current ?? null, [data, activeId]);
  const connectedRegistrationForm = data?.connections.find((item) => item.provider === "provider_embed" && item.status === "connected") ?? null;
  const websiteHandoffRecord = object(funnel?.assetJson.websiteHandoff);
  const websiteHandoffPageId = text(websiteHandoffRecord.pageId, "");
  const activeWebsiteJob = data?.websiteHandoff.activeJob ?? null;
  const requestedFromSiteArchitect = searchParams.get("source") === "site-architect";
  useEffect(() => {
    if (!activeWebsiteJob) return;
    const timer = window.setInterval(() => {
      void api.get<Response>(`/api/projects/${projectId}/lead-magnets`).then(setData).catch(() => undefined);
    }, 4_000);
    return () => window.clearInterval(timer);
  }, [activeWebsiteJob?.id, projectId]);
  const leadMagnets = useMemo(() => {
    const latestBySeries = new Map<string, Funnel>();
    for (const item of data?.funnels ?? []) {
      const current = latestBySeries.get(item.seriesId);
      if (!current || item.version > current.version) latestBySeries.set(item.seriesId, item);
    }
    return [...latestBySeries.values()];
  }, [data]);
  const selectedVersions = useMemo(() => funnel ? (data?.funnels ?? []).filter((item) => item.seriesId === funnel.seriesId).sort((a, b) => b.version - a.version) : [], [data, funnel]);
  const visibleTabs = data?.capabilities.clientViewer ? tabs.slice(0, 4) : tabs;
  const businessEvidence = object(researchData.evidence?.businessIntake);
  const geographyEvidence = object(researchData.evidence?.geography);
  const keywordEvidence = object(researchData.evidence?.keywords);
  const siteEvidence = object(researchData.evidence?.siteAnalysis);
  const opportunityEvidence = object(researchData.evidence?.selectedOpportunity);
  const strategyEvidence = object(researchData.evidence?.strategyAndSeoPlan);
  const refreshDiscovery = object(researchData.evidence?.liveRefreshDiscovery);
  const refreshSources = list(refreshDiscovery.sources).map(object);
  const measuredKeywords = list(keywordEvidence.measuredKeywords).map(object);
  const currentRecommendationCount = recommendations.filter((item) => item.recommendationSet !== "previous").length;
  const targetWordCountNumber = Number(targetWordCount);
  const hasValidTargetWordCount = targetWordCount.trim().length > 0 && Number.isInteger(targetWordCountNumber) && targetWordCountNumber >= 250 && targetWordCountNumber <= 10_000;
  const funnelConversionTarget = Number(generationFunnelSetup.conversionTarget);
  const hasValidConversionTarget = Number.isFinite(funnelConversionTarget) && funnelConversionTarget >= .1 && funnelConversionTarget <= 100;
  const exportUrl = (kind: string, preview = false) => funnel ? `/api/projects/${projectId}/lead-magnets/${funnel.id}/export/${kind}${preview ? "?preview=1" : ""}` : "#";

  const run = async (key: string, action: () => Promise<unknown>, success: string, preferNewestRecommendation = false) => {
    setBusy(key); setNotice(null);
    try { await action(); await load(preferNewestRecommendation); setNotice({ tone: "success", text: success }); return true; }
    catch (error) { setNotice({ tone: "error", text: error instanceof Error ? error.message : "The action could not be completed." }); return false; }
    finally { setBusy(""); }
  };
  useEffect(() => {
    if (setupStep === 0 || !data?.capabilities.canGenerate || researchData.researchRun || autoResearchAttempted || busy) return;
    setAutoResearchAttempted(true);
    void run("research", () => api.post(`/api/projects-v2/${projectId}/lead-magnet/research`, { objective: null, desiredAction: "generate_qualified_leads", preferredFormat: null, successDefinition: null, notes: null, researchMode: "primary" }), "Primary AI research is complete. Review the recommendation and supporting evidence, then answer the refinement questions if needed.");
  }, [data, researchData.researchRun, autoResearchAttempted, busy, projectId, setupStep]);
  const generate = (recommendation?: Recommendation, setupInstructions?: string, visuals = generationVisuals) => {
    if (!researchData.researchRun) { setNotice({ tone: "error", text: "Run the AI research step before generating a lead magnet." }); return Promise.resolve(false); }
    const idea = recommendation?.title || selectedIdea || null;
    const selectedRecommendation = recommendation ?? recommendations.find((item) => item.title === idea && (!selectedResearchRunId || item.researchRunId === selectedResearchRunId));
    if (recommendation) { setCustomType(""); setSelectedIdea(recommendation.title); setSelectedResearchRunId(recommendation.researchRunId ?? null); }
    let generatedFunnelId = "";
    return run("generate", async () => {
      const requestedWords = Number(targetWordCount);
      const conversionTarget = Number(generationFunnelSetup.conversionTarget);
      const optional = (value: string) => value.trim() || null;
      const funnelSetup = { contentMode: generationFunnelSetup.contentMode, leadMagnetTitle: optional(generationFunnelSetup.leadMagnetTitle), landingHeadline: optional(generationFunnelSetup.landingHeadline), landingDescription: optional(generationFunnelSetup.landingDescription), ctaText: optional(generationFunnelSetup.ctaText), deliveryEmailSubject: optional(generationFunnelSetup.deliveryEmailSubject), deliveryEmailContent: optional(generationFunnelSetup.deliveryEmailContent), conversionTarget: Number.isFinite(conversionTarget) && conversionTarget >= .1 && conversionTarget <= 100 ? conversionTarget : 5 };
      const result = await api.post<{ funnel: { id: string } }>(`/api/projects-v2/${projectId}/lead-magnet/generate`, { researchRunId: selectedRecommendation?.researchRunId ?? researchData.researchRun?.id, seriesId: generationSeriesId, selectedIdea: idea, instructions: setupInstructions || instructions || null, recommendation: selectedRecommendation ?? null, targetWordCount: Number.isFinite(requestedWords) && requestedWords >= 250 ? requestedWords : null, funnelSetup, visuals });
      generatedFunnelId = result.funnel.id;
    }, "A new lead magnet and its complete funnel were generated for this project.").then((completed) => {
      if (completed && generatedFunnelId) setActiveId(generatedFunnelId);
      return completed;
    });
  };
  const startSetup = (recommendation?: Recommendation, step: 1 | 2 = 1) => {
    if (recommendation) { setCustomType(""); setSelectedIdea(recommendation.title); setSelectedResearchRunId(recommendation.researchRunId ?? null); }
    setGenerationAudience((current) => current || text(businessEvidence.targetAudience, ""));
    setGenerationCta((current) => current || (desiredAction === "increase_quotes_or_bookings" ? "Request a quote or booking" : desiredAction === "grow_email_list" ? "Join the email list" : "Take the next recommended action"));
    setSetupStep(step);
    setNotice(null);
  };
  const beginGeneration = async () => {
    const recommendation = recommendations.find((item) => item.title === selectedIdea && (!selectedResearchRunId || item.researchRunId === selectedResearchRunId));
    const setupInstructions = [
      objective && `Goal: ${objective}`,
      desiredAction && `Desired result: ${label(desiredAction)}`,
      successDefinition && `Success definition: ${successDefinition}`,
      instructions,
      generationAudience && `Audience refinement: ${generationAudience}`,
      generationCta && `Primary CTA or next action: ${generationCta}`,
      generationDetails && `Must-cover details and constraints: ${generationDetails}`,
    ].filter(Boolean).join("\n");
    setSetupStep(4);
    const completed = await generate(recommendation, setupInstructions);
    if (completed) { setSetupStep(0); setTab("Funnel assets"); }
    else setSetupStep(4);
  };
  const startNewLeadMagnet = () => {
    setGenerationSeriesId(null);
    setGenerationAudience(text(businessEvidence.targetAudience, ""));
    setGenerationCta(desiredAction === "increase_quotes_or_bookings" ? "Request a quote or booking" : desiredAction === "grow_email_list" ? "Join the email list" : "Take the next recommended action");
    setGenerationDetails("");
    setTargetWordCount("");
    setGenerationVisuals({ charts: true, images: true, diagrams: true });
    setGenerationFunnelSetup({ contentMode: "sales_pitch", leadMagnetTitle: "", landingHeadline: "", landingDescription: "", ctaText: "", deliveryEmailSubject: "", deliveryEmailContent: "", conversionTarget: "5" });
    setCustomType("");
    setSelectedIdea(recommendations[0]?.title || "");
    setSelectedResearchRunId(recommendations[0]?.researchRunId ?? null);
    setSetupStep(1);
    setNotice(null);
  };
  useEffect(() => {
    if (startRequestKey > 0 && data?.capabilities.canGenerate) startNewLeadMagnet();
  }, [startRequestKey, data?.capabilities.canGenerate]);
  const refineLeadMagnet = () => {
    if (!funnel) return;
    setGenerationSeriesId(funnel.seriesId);
    setTargetWordCount(typeof funnel.assetJson.targetWordCount === "number" ? String(funnel.assetJson.targetWordCount) : "");
    setGenerationFunnelSetup({ contentMode: funnel.landingPageJson.contentMode === "full_content" ? "full_content" : "sales_pitch", leadMagnetTitle: funnel.title, landingHeadline: text(funnel.landingPageJson.headline, ""), landingDescription: text(funnel.landingPageJson.subheadline, ""), ctaText: text(funnel.landingPageJson.ctaText, text(funnel.optInFormJson.submitLabel, "")), deliveryEmailSubject: text(funnel.deliveryEmailJson.subject, ""), deliveryEmailContent: text(funnel.deliveryEmailJson.body, ""), conversionTarget: String(funnel.conversionTarget ?? 5) });
    startSetup(undefined, 1);
  };
  const refreshResearch = () => {
    setCustomType("");
    setSelectedIdea("");
    setSelectedResearchRunId(null);
    void run("research", () => api.post(`/api/projects-v2/${projectId}/lead-magnet/research`, {
      objective: objective || null,
      desiredAction,
      preferredFormat: null,
      successDefinition: successDefinition || null,
      notes: instructions || null,
      researchMode: "refresh",
      excludedRecommendationTitles: recommendations.map((item) => item.title).slice(0, 5),
    }), "Fresh discovery is complete. AI explored different keywords, buyer questions, source evidence, and lead-magnet angles. Your previous suggestions remain available for comparison.", true);
  };
  const continueToFunnelSetup = () => {
    const selectedRecommendation = recommendations.find((item) => item.title === selectedIdea && (!selectedResearchRunId || item.researchRunId === selectedResearchRunId));
    setGenerationFunnelSetup((current) => ({
      ...current,
      leadMagnetTitle: current.leadMagnetTitle || selectedRecommendation?.title || "",
      ctaText: current.ctaText || generationCta,
    }));
    setSetupStep(4);
  };
  const navigateSetupStep = (step: 1 | 2 | 3 | 4) => {
    if (!generationSeriesId || !researchData.research) return;
    if (step === 4) continueToFunnelSetup();
    else setSetupStep(step);
    setNotice(null);
  };
  const openLeadMagnet = (item: Funnel) => {
    setActiveId(item.id);
    setSetupStep(0);
    setTab("Funnel assets");
    window.setTimeout(() => document.getElementById("lead-magnet-results")?.scrollIntoView({ behavior: "smooth", block: "start" }), 0);
  };
  const approve = () => funnel && window.confirm(`Approve ${funnel.title} v${funnel.version}? This locks the exact asset version. Publishing will still require a validated registration form.`) && run("approve", () => api.post(`/api/projects/${projectId}/lead-magnets/${funnel.id}/approve`, { comments: "Approved after reviewing all funnel assets." }), "Lead Magnet Ready. The approved asset can now be downloaded or connected to a landing-page draft. Registration and delivery are still required before publishing.");
  const connect = () => run("connect", () => api.post(`/api/projects/${projectId}/lead-magnets/esp/connect`, {
    provider: "provider_embed",
    providerName,
    embedCode: providerEmbedCode,
    listName: providerName || "Preferred email provider",
    fieldMappings: {},
  }), `${providerName || "Provider"} form was validated and saved. You can now publish the funnel.`);
  const openEmailSetup = () => {
    setTab("Integration");
    setNotice({ tone: "info", text: "Paste the official registration-form embed from your email or CRM provider, validate it, and then publish." });
    window.setTimeout(() => document.getElementById("lead-magnet-email-setup")?.scrollIntoView({ behavior: "smooth", block: "start" }), 0);
  };
  const publish = () => {
    if (!funnel) return;
    if (!connectedRegistrationForm) { openEmailSetup(); return; }
    if (!window.confirm(`Publish ${funnel.title} with the ${connectedRegistrationForm.listName || "provider"} registration form?`)) return;
    void run("publish", () => api.post(`/api/projects/${projectId}/lead-magnets/${funnel.id}/publish`, { connectionId: connectedRegistrationForm.id, shareWithClient: funnel.sharedWithClient }), "The funnel was validated and published with the provider registration form.");
  };
  const saveMetrics = () => funnel && run("metrics", () => api.post(`/api/projects/${projectId}/lead-magnets/${funnel.id}/metrics`, Object.fromEntries(Object.entries(metrics).map(([key, value]) => [key, Number(value || 0)]))), "Performance was saved and optimization recommendations were recalculated.");
  const downloadExport = (kind: string) => { setNotice(null); void api.download(exportUrl(kind)).catch((error) => setNotice({ tone: "error", text: error instanceof Error ? error.message : "The export could not be downloaded." })); };
  const previewWidget = () => { setNotice(null); void api.preview(exportUrl("widget", true)).catch((error) => setNotice({ tone: "error", text: error instanceof Error ? error.message : "The widget preview could not be opened." })); };
  const openWebsiteHandoff = () => {
    if (!funnel) return;
    if (!data?.websiteHandoff.siteArchitectReady) {
      setNotice({ tone: "error", text: "Start the website in Site Architect before connecting this lead magnet." });
      return;
    }
    if (activeWebsiteJob) {
      setNotice({ tone: "info", text: `Website generation is ${activeWebsiteJob.status} (${activeWebsiteJob.progress}%). This page can be connected as soon as that job finishes; this screen will refresh automatically.` });
      return;
    }
    const landing = object(funnel.landingPageJson);
    const seo = object(funnel.seoMetadataJson);
    const savedSlug = text(websiteHandoffRecord.slug, "");
    setWebsiteHandoff({
      title: text(websiteHandoffRecord.pageTitle, text(landing.headline, funnel.title)),
      slug: savedSlug || funnel.title.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "").slice(0, 80),
      primaryKeyword: text(seo.primaryKeyword, text(seo.title, funnel.title)),
      targetCta: text(landing.ctaText, text(funnel.optInFormJson.submitLabel, "Get the resource")).slice(0, 40),
      includeInNavigation: false,
    });
    setWebsiteHandoffOpen(true);
    setNotice(null);
  };
  const handoffToWebsite = async () => {
    if (!funnel) return;
    setBusy("website-handoff"); setNotice(null);
    try {
      const result = await api.post<{ siteArchitectUrl: string; contentPrepared: boolean; nextAction: string }>(`/api/projects/${projectId}/lead-magnets/${funnel.id}/website-handoff`, websiteHandoff);
      setWebsiteHandoffOpen(false);
      await load();
      navigate(result.siteArchitectUrl);
    } catch (error) {
      setNotice({ tone: "error", text: error instanceof Error ? error.message : "The landing page could not be added to Site Architect." });
    } finally { setBusy(""); }
  };

  if (!data) return <LeadMagnetPageLoading />;
  if (data.capabilities.clientViewer && !funnel) return <Empty title="No approved lead assets have been shared" detail="Client Viewers can only see published lead funnels explicitly shared for their projects." />;
  const performanceAvailable = funnel ? Object.values(funnel.performance).some((value) => Number(value) > 0) : false;
  return <div className="space-y-5">
    {busy === "research" && <LeadMagnetCookingScreen refreshing={Boolean(researchData.researchRun)} />}
    {busy === "generate" && <LeadFunnelGenerationCookingScreen />}
    {notice && <div className={`rounded-xl border px-4 py-3 text-sm font-semibold ${notice.tone === "success" ? "border-emerald-200 bg-emerald-50 text-emerald-900" : notice.tone === "info" ? "border-cyan-200 bg-cyan-50 text-cyan-950" : "border-rose-200 bg-rose-50 text-rose-900"}`}>{notice.text}</div>}
    <section className="overflow-hidden rounded-2xl border border-slate-200 bg-white shadow-sm" aria-label="Current creation context"><div className="border-b border-slate-100 bg-slate-50 px-4 py-2 text-[10px] font-black uppercase tracking-[.14em] text-slate-500">Current creation context</div><div className="grid gap-px bg-slate-100 sm:grid-cols-2 xl:grid-cols-5">{[["Workspace", data.context.workspaceName], ["Client", data.context.clientName || "This business"], ["Project", data.context.projectName], ["Business", data.context.businessName], ["Website", data.context.websiteName || "Website not selected"]].map(([itemLabel, value]) => <div key={itemLabel} className="min-w-0 bg-white px-4 py-3"><div className="text-[9px] font-black uppercase tracking-wide text-slate-400">{itemLabel}</div><div className="mt-1 truncate text-xs font-bold text-slate-800" title={value}>{value}</div></div>)}</div>{requestedFromSiteArchitect && <div className="flex flex-col gap-3 border-t border-cyan-200 bg-cyan-50 px-5 py-4 sm:flex-row sm:items-center sm:justify-between"><div><div className="text-xs font-black uppercase tracking-wide text-cyan-700">Source · Site Architect landing-page action</div><p className="mt-1 text-sm leading-6 text-cyan-950">Create and approve the lead magnet, then connect that exact version to a landing-page draft. Form and delivery setup can be completed before publishing.</p></div><button type="button" onClick={() => navigate(searchParams.get("returnTo") || `/site-architect?projectId=${encodeURIComponent(projectId)}`)} className="shrink-0 rounded-lg border border-cyan-300 bg-white px-4 py-2.5 text-sm font-bold text-cyan-800">Return to website</button></div>}</section>

    {(setupStep > 0 || Boolean(funnel)) && <section className="overflow-hidden rounded-2xl border border-slate-200 bg-white shadow-sm">
      {data.capabilities.canGenerate && setupStep > 0 && <div className="flex flex-col gap-6 border-b border-slate-100 bg-slate-50/60 p-5">
        {setupStep > 0 && <section className="rounded-2xl border border-brand-200 bg-white p-5 shadow-sm">
          <div className="grid gap-2 sm:grid-cols-2 xl:grid-cols-4">{[["1", "Primary AI suggestion"], ["2", "Exhaustive primary research"], ["3", "Refine the recommendation"], ["4", "Funnel content setup"]].map(([number, title], index) => { const stepNumber = (index + 1) as 1 | 2 | 3 | 4; const active = setupStep === stepNumber; const complete = setupStep > stepNumber; const editableNavigation = Boolean(generationSeriesId && researchData.research); return <button type="button" key={number} onClick={() => navigateSetupStep(stepNumber)} disabled={!editableNavigation} aria-current={active ? "step" : undefined} className={`rounded-xl border px-4 py-3 text-left transition ${active ? "border-brand-500 bg-brand-50" : complete ? "border-emerald-200 bg-emerald-50" : "border-slate-200 bg-slate-50"} ${editableNavigation ? "cursor-pointer hover:border-brand-400 hover:shadow-sm" : "cursor-default"}`}><div className={`grid h-7 w-7 place-items-center rounded-full text-xs font-black ${active ? "bg-brand-600 text-white" : complete ? "bg-emerald-600 text-white" : "bg-slate-200 text-slate-600"}`}>{complete ? "✓" : number}</div><div className="mt-2 text-sm font-bold text-slate-900">{title}</div>{editableNavigation && <div className="mt-1 text-xs font-semibold text-brand-600">{active ? "Current step" : "Open step"}</div>}</button>; })}</div>
          {generationSeriesId && <p className="mt-3 text-xs font-semibold text-brand-700">Editing setup: select any step above to review or change it.</p>}
          <div className="mt-3 flex justify-end"><button type="button" onClick={() => setSetupStep(0)} className="rounded-lg border border-slate-200 px-3 py-2 text-xs font-bold text-slate-600">{funnel ? "Return to results" : "Cancel setup"}</button></div>
        </section>}
        {setupStep > 0 && !researchData.research && <section className="order-1 rounded-2xl border border-brand-200 bg-white p-8 text-center">{busy === "research" && <div className="mx-auto h-10 w-10 animate-spin rounded-full border-4 border-brand-100 border-t-brand-600" />}<div className="mt-4 text-xs font-bold uppercase tracking-wide text-brand-600">Primary AI research</div><h3 className="mt-1 text-lg font-bold text-slate-950">{busy === "research" ? "Researching the strongest lead opportunity" : "Primary research needs to be run"}</h3><p className="mx-auto mt-2 max-w-2xl text-sm leading-6 text-slate-500">Reviewing Business Intake, keywords, geography, Site Analysis, selected Opportunity, approved Strategy, and SEO plan before asking you to refine anything.</p>{busy !== "research" && <button type="button" onClick={() => setAutoResearchAttempted(false)} className="mt-4 rounded-lg bg-brand-600 px-5 py-2.5 text-sm font-bold text-white">Retry primary AI research</button>}</section>}
        {setupStep === 3 && researchData.research && <section className="order-3 rounded-2xl border border-slate-200 bg-white p-5">
          <div className="text-xs font-bold uppercase tracking-wide text-brand-600">Step 3 · Refine the recommendation</div>
          <h3 className="mt-1 text-lg font-bold text-slate-950">Answer only what AI still needs to know</h3>
          <p className="mt-1 text-sm leading-6 text-slate-500">The primary recommendation is already available above. Use these questions and controls only when you want AI to adjust the direction.</p>
          {researchData.followUpQuestions?.length > 0 && <div className="mt-4 grid gap-3 lg:grid-cols-2">{researchData.followUpQuestions.map((item, index) => <div key={index} className="rounded-xl border border-violet-100 bg-violet-50 p-4"><div className="text-sm font-bold text-violet-950">{item.question}</div><p className="mt-1 text-xs leading-5 text-violet-700">{item.why}</p>{item.suggestedAnswer && <p className="mt-2 text-xs font-semibold text-slate-600">AI starting point: {item.suggestedAnswer}</p>}</div>)}</div>}
          <div className="mt-4 grid gap-4 lg:grid-cols-2">
            <div className="space-y-3"><label className="block"><span className="text-xs font-bold text-slate-600">Planned result *</span><textarea value={objective} onChange={(event) => setObjective(event.target.value)} rows={4} maxLength={1000} placeholder="Example: Capture qualified visitor-insurance prospects and move them toward requesting a quote." className="mt-1 w-full rounded-xl border border-slate-300 px-3 py-2 text-sm outline-none focus:border-brand-500" /></label><label className="block"><span className="text-xs font-bold text-slate-600">Research notes or constraints</span><textarea value={instructions} onChange={(event) => setInstructions(event.target.value)} rows={3} maxLength={2000} placeholder="Add must-cover topics, audience constraints, offer details, tone, or anything AI should avoid." className="mt-1 w-full rounded-xl border border-slate-300 px-3 py-2 text-sm outline-none focus:border-brand-500" /></label></div>
            <div className="space-y-3">
              <label className="block"><span className="text-xs font-bold text-slate-600">Desired customer action</span><select value={desiredAction} onChange={(event) => setDesiredAction(event.target.value)} className="mt-1 w-full rounded-xl border border-slate-300 bg-white px-3 py-2 text-sm"><option value="grow_email_list">Join the email list</option><option value="generate_qualified_leads">Become a qualified lead</option><option value="increase_quotes_or_bookings">Request a quote or booking</option><option value="promote_an_offer">Consider an offer</option><option value="educate_prospects">Understand the problem or solution</option><option value="other">Another outcome</option></select></label>
              <label className="block"><span className="text-xs font-bold text-slate-600">How will success be recognized?</span><input value={successDefinition} onChange={(event) => setSuccessDefinition(event.target.value)} maxLength={500} placeholder="Example: More qualified quote requests from Ontario visitors" className="mt-1 w-full rounded-xl border border-slate-300 px-3 py-2 text-sm outline-none focus:border-brand-500" /></label>
              <label className="block"><span className="text-xs font-bold text-slate-600">Choose another supported format</span><select value={customType} onChange={(event) => { const value = event.target.value; setCustomType(value); setTargetWordCount(""); setSelectedIdea(value ? `Create a project-specific ${value} using the completed lead-magnet research and the strongest conversion angle.` : recommendations[0]?.title ?? ""); setSelectedResearchRunId(value ? null : recommendations[0]?.researchRunId ?? null); }} className="mt-1 w-full rounded-xl border border-slate-300 bg-white px-3 py-2 text-sm"><option value="">Let AI recommend the best format</option>{supportedTypes.map((item) => <option key={item}>{item}</option>)}</select></label>
              <label className="block"><span className="text-xs font-bold text-slate-600">Target number of words{customType ? " *" : ""}</span><input type="number" min={250} max={10000} step={250} required={Boolean(customType)} value={targetWordCount} onChange={(event) => setTargetWordCount(event.target.value)} placeholder={customType ? `Enter the length for ${customType}` : "Let AI choose the best length"} className="mt-1 w-full rounded-xl border border-slate-300 bg-white px-3 py-2 text-sm outline-none focus:border-brand-500" /><span className="mt-1 block text-xs leading-5 text-slate-500">Applies to the lead-magnet body for every format. AI aims to stay within approximately 10% of your target.</span></label>
            </div>
          </div>
          <div className="mt-5 border-t border-slate-100 pt-5"><div className="text-sm font-bold text-slate-950">Three final setup details</div><div className="mt-3 grid gap-4"><label><span className="text-xs font-bold text-slate-600">1. Audience refinement</span><input value={generationAudience} onChange={(event) => setGenerationAudience(event.target.value)} maxLength={500} placeholder="Who specifically should this lead magnet attract?" className="mt-1 w-full rounded-xl border border-slate-300 px-3 py-2.5 text-sm outline-none focus:border-brand-500" /></label><label><span className="text-xs font-bold text-slate-600">2. Primary CTA or next action</span><input value={generationCta} onChange={(event) => setGenerationCta(event.target.value)} maxLength={300} placeholder="What should the lead do after receiving it?" className="mt-1 w-full rounded-xl border border-slate-300 px-3 py-2.5 text-sm outline-none focus:border-brand-500" /></label><label><span className="text-xs font-bold text-slate-600">3. Must-cover details or constraints</span><textarea value={generationDetails} onChange={(event) => setGenerationDetails(event.target.value)} rows={4} maxLength={1500} placeholder="Topics, offer details, compliance notes, tone, exclusions, or required information." className="mt-1 w-full rounded-xl border border-slate-300 px-3 py-2.5 text-sm outline-none focus:border-brand-500" /></label></div></div>
          <div className="mt-5 rounded-xl border border-slate-200 bg-slate-50 p-4"><div className="text-sm font-bold text-slate-950">AI-researched charts, images, and diagrams</div><p className="mt-1 text-xs leading-5 text-slate-500">Choose the visual types you want for any lead-magnet format. SEnuke AI - AI Growth Operating System will search for credible evidence, select the sources, generate original visuals, and attach clickable citations automatically.</p><div className="mt-3 flex flex-wrap gap-4">{([["charts", "Research & generate charts"], ["images", "Research & generate images"], ["diagrams", "Research & generate diagrams"]] as const).map(([key, visualLabel]) => <label key={key} className="flex items-center gap-2 text-sm font-semibold text-slate-700"><input type="checkbox" checked={generationVisuals[key]} onChange={(event) => setGenerationVisuals((current) => ({ ...current, [key]: event.target.checked }))} className="h-4 w-4 rounded border-slate-300 text-brand-600" />{visualLabel}</label>)}</div><div className="mt-3 rounded-lg border border-emerald-200 bg-emerald-50 px-3 py-2 text-xs font-semibold leading-5 text-emerald-900">No source entry is required. AI researches each selected visual and shows its evidence source beneath the generated result and in downloads.</div></div>
          <div className="mt-5 flex flex-wrap justify-between gap-2"><button type="button" onClick={() => setSetupStep(2)} className="rounded-lg border border-slate-200 px-4 py-2.5 text-sm font-bold text-slate-700">← Back to research</button><button type="button" onClick={continueToFunnelSetup} disabled={Boolean(busy) || objective.trim().length < 10 || !selectedIdea || (Boolean(customType) && !hasValidTargetWordCount)} className="rounded-lg bg-brand-600 px-6 py-3 text-sm font-black text-white disabled:opacity-50">Continue to funnel content →</button></div>
        </section>}

        {setupStep === 4 && researchData.research && <section className="order-4 rounded-2xl border border-slate-200 bg-white p-5">
          <div className="text-xs font-bold uppercase tracking-wide text-brand-600">Step 4 · Funnel content setup</div>
          <h3 className="mt-1 text-lg font-bold text-slate-950">Set the customer-facing funnel content</h3>
          <p className="mt-1 text-sm leading-6 text-slate-500">Review or enter the values you want AI to use exactly. Leave optional copy blank when you want AI to create it from the completed research.</p>
          <div className="mt-5 grid gap-4 lg:grid-cols-2">
            <fieldset className="lg:col-span-2"><legend className="text-xs font-bold text-slate-600">Landing-page content</legend><div className="mt-2 grid gap-3 sm:grid-cols-2"><label className={`cursor-pointer rounded-xl border p-4 ${generationFunnelSetup.contentMode === "sales_pitch" ? "border-brand-400 bg-brand-50 ring-2 ring-brand-100" : "border-slate-200 bg-white"}`}><input type="radio" name="landing-content-mode" value="sales_pitch" checked={generationFunnelSetup.contentMode === "sales_pitch"} onChange={() => setGenerationFunnelSetup((current) => ({ ...current, contentMode: "sales_pitch" }))} className="mr-2" /><b className="text-sm text-slate-950">Sales pitch + registration</b><span className="mt-1 block text-xs leading-5 text-slate-500">Show the promise, benefits, selected previews, proof and FAQs. Keep the complete lead magnet gated for delivery after registration.</span></label><label className={`cursor-pointer rounded-xl border p-4 ${generationFunnelSetup.contentMode === "full_content" ? "border-violet-400 bg-violet-50 ring-2 ring-violet-100" : "border-slate-200 bg-white"}`}><input type="radio" name="landing-content-mode" value="full_content" checked={generationFunnelSetup.contentMode === "full_content"} onChange={() => setGenerationFunnelSetup((current) => ({ ...current, contentMode: "full_content" }))} className="mr-2" /><b className="text-sm text-slate-950">Full promotional content + registration</b><span className="mt-1 block text-xs leading-5 text-slate-500">Publish the complete generated content on the page and keep registration, enquiry or offer CTAs visible. Useful for real estate, products, events and public offers.</span></label></div></fieldset>
            <label className="block"><span className="text-xs font-bold text-slate-600">Lead-magnet title</span><input value={generationFunnelSetup.leadMagnetTitle} onChange={(event) => setGenerationFunnelSetup((current) => ({ ...current, leadMagnetTitle: event.target.value }))} maxLength={255} placeholder="Let AI create the title" className="mt-1 w-full rounded-xl border border-slate-300 px-3 py-2.5 text-sm outline-none focus:border-brand-500" /></label>
            <label className="block"><span className="text-xs font-bold text-slate-600">Conversion target (%) *</span><input type="number" min={.1} max={100} step={.1} required value={generationFunnelSetup.conversionTarget} onChange={(event) => setGenerationFunnelSetup((current) => ({ ...current, conversionTarget: event.target.value }))} className="mt-1 w-full rounded-xl border border-slate-300 px-3 py-2.5 text-sm outline-none focus:border-brand-500" /><span className="mt-1 block text-xs text-slate-500">Used to compare actual opt-in performance and trigger improvement recommendations.</span></label>
            <label className="block"><span className="text-xs font-bold text-slate-600">Landing-page headline</span><input value={generationFunnelSetup.landingHeadline} onChange={(event) => setGenerationFunnelSetup((current) => ({ ...current, landingHeadline: event.target.value }))} maxLength={240} placeholder="Let AI write the headline" className="mt-1 w-full rounded-xl border border-slate-300 px-3 py-2.5 text-sm outline-none focus:border-brand-500" /></label>
            <label className="block"><span className="text-xs font-bold text-slate-600">CTA button text</span><input value={generationFunnelSetup.ctaText} onChange={(event) => setGenerationFunnelSetup((current) => ({ ...current, ctaText: event.target.value }))} maxLength={120} placeholder="Example: Send me the guide" className="mt-1 w-full rounded-xl border border-slate-300 px-3 py-2.5 text-sm outline-none focus:border-brand-500" /></label>
            <label className="block lg:col-span-2"><span className="text-xs font-bold text-slate-600">Landing-page description</span><textarea value={generationFunnelSetup.landingDescription} onChange={(event) => setGenerationFunnelSetup((current) => ({ ...current, landingDescription: event.target.value }))} rows={3} maxLength={600} placeholder="Let AI explain the value and benefits" className="mt-1 w-full rounded-xl border border-slate-300 px-3 py-2.5 text-sm outline-none focus:border-brand-500" /></label>
            <label className="block"><span className="text-xs font-bold text-slate-600">Delivery email subject</span><input value={generationFunnelSetup.deliveryEmailSubject} onChange={(event) => setGenerationFunnelSetup((current) => ({ ...current, deliveryEmailSubject: event.target.value }))} maxLength={240} placeholder="Let AI write the subject" className="mt-1 w-full rounded-xl border border-slate-300 px-3 py-2.5 text-sm outline-none focus:border-brand-500" /></label>
            <label className="block lg:col-span-2"><span className="text-xs font-bold text-slate-600">Delivery email content</span><textarea value={generationFunnelSetup.deliveryEmailContent} onChange={(event) => setGenerationFunnelSetup((current) => ({ ...current, deliveryEmailContent: event.target.value }))} rows={6} maxLength={10000} placeholder="Let AI write the delivery email, or enter the exact content to use" className="mt-1 w-full rounded-xl border border-slate-300 px-3 py-2.5 text-sm outline-none focus:border-brand-500" /></label>
          </div>
          <div className="mt-5 flex flex-wrap justify-between gap-2"><button type="button" onClick={() => setSetupStep(3)} className="rounded-lg border border-slate-200 px-4 py-2.5 text-sm font-bold text-slate-700">← Back to refinement</button><button type="button" onClick={() => void beginGeneration()} disabled={Boolean(busy) || !hasValidConversionTarget} className="rounded-lg bg-slate-950 px-6 py-3 text-sm font-black text-white disabled:opacity-50">{generationSeriesId ? "Generate refined version with AI" : "Generate with AI"}</button></div>
        </section>}

        {setupStep === 2 && researchData.research && <section className="order-2">
          <div className="text-xs font-bold uppercase tracking-wide text-brand-600">Step 2 · Exhaustive primary research</div>
          <h3 className="mt-1 text-lg font-bold text-slate-950">Everything AI reviewed before making the suggestion</h3>
          <div className="mt-3 grid gap-3 md:grid-cols-2 xl:grid-cols-3">
            <ResearchCard title="Business intake" detail={text(businessEvidence.businessName, "Business profile")} values={[text(businessEvidence.targetAudience, ""), text(businessEvidence.offer, ""), text(businessEvidence.primaryGoal, "")].filter(Boolean)} />
            <ResearchCard title="Keywords" detail={`${measuredKeywords.length} measured or researched terms`} values={measuredKeywords.slice(0, 5).map((item) => `${text(item.keyword, "Keyword")}${typeof item.monthlySearches === "number" && item.monthlySearches > 0 ? ` · ${item.monthlySearches.toLocaleString()} searches` : ""}`)} />
            <ResearchCard title="Geography" detail={text(geographyEvidence.businessLocation, "Business location not provided")} values={list(geographyEvidence.targetMarkets).map(String)} />
            <ResearchCard title="Site analysis" detail={siteEvidence.available === false ? text(siteEvidence.reason) : `${Number(siteEvidence.pagesCrawled ?? 0)} pages · score ${String(siteEvidence.siteScore ?? "not scored")}`} values={list(siteEvidence.openIssues).slice(0, 4).map((item) => text(object(item).message, text(object(item).issueType)))} />
            <ResearchCard title="Selected opportunity" detail={text(opportunityEvidence.name, text(opportunityEvidence.reason, "No selected opportunity"))} values={[text(opportunityEvidence.summary, ""), text(opportunityEvidence.recommendedOffer, "")].filter(Boolean)} />
            <ResearchCard title="Strategy and SEO plan" detail={text(strategyEvidence.status, text(strategyEvidence.reason, "No approved strategy"))} values={[text(strategyEvidence.strategySummary, ""), text(strategyEvidence.seoStrategy, ""), text(strategyEvidence.contentStrategy, "")].filter(Boolean)} />
            {refreshSources.length > 0 && <section className="rounded-xl border border-violet-200 bg-violet-50 p-4"><div className="text-xs font-bold uppercase tracking-wide text-violet-700">Fresh external discovery</div><div className="mt-1 text-sm font-bold text-slate-900">{refreshSources.length} new source{refreshSources.length === 1 ? "" : "s"} reviewed</div><div className="mt-2 space-y-1">{refreshSources.slice(0, 5).map((source, index) => <a key={index} href={text(source.url, "#")} target="_blank" rel="noreferrer" className="block truncate text-xs font-semibold text-violet-700 underline">{text(source.title, text(source.url))}</a>)}</div></section>}
          </div>
          <div className="mt-4 grid gap-4 lg:grid-cols-2">
            <Panel title="AI research findings" eyebrow="Evidence synthesis"><p className="text-sm leading-6 text-slate-700">{researchData.research.objectiveSummary}</p><Rows title="Audience needs" values={researchData.research.audienceNeeds} /><Rows title="Keyword and search intent" values={researchData.research.keywordInsights} /><Rows title="Geographic insights" values={researchData.research.geographicInsights} /></Panel>
            <Panel title="Opportunity analysis" eyebrow="Research before recommendation"><Rows title="Website findings" values={researchData.research.siteInsights} /><Rows title="Lead-capture gaps" values={researchData.research.opportunityGaps} /><div className="mt-4 rounded-xl bg-brand-50 p-4 text-sm leading-6 text-brand-950"><b>Recommended strategy:</b> {researchData.research.recommendedStrategy}</div><Rows title="Research limits" values={researchData.research.researchLimits} /></Panel>
          </div>
          <div className="mt-5 flex justify-between gap-2"><button type="button" onClick={() => setSetupStep(1)} className="rounded-lg border border-slate-200 px-4 py-2.5 text-sm font-bold text-slate-700">← Back to suggestions</button><button type="button" onClick={() => setSetupStep(3)} className="rounded-lg bg-brand-600 px-5 py-2.5 text-sm font-bold text-white">Continue to refine →</button></div>
        </section>}

        {setupStep === 1 && researchData.research && <section className="order-1">
          <div className="flex flex-col gap-3 sm:flex-row sm:items-end sm:justify-between"><div><div className="text-xs font-bold uppercase tracking-wide text-brand-600">Step 1 · Primary AI suggestion</div><h3 className="mt-1 text-lg font-bold text-slate-950">Best options from the completed research</h3></div><button type="button" onClick={refreshResearch} disabled={Boolean(busy)} className="w-fit rounded-lg border border-brand-200 bg-white px-4 py-2 text-sm font-bold text-brand-700 hover:bg-brand-50 disabled:opacity-50">{busy === "research" ? "Finding different angles…" : "Find different AI options"}</button></div>
          <div className="mt-3 grid gap-3 lg:grid-cols-2">{recommendations.map((item, index) => <Fragment key={`${item.researchRunId ?? "research"}-${item.type}-${item.title}`}><div className={`${index === 0 || index === currentRecommendationCount ? "block" : "hidden"} lg:col-span-2`}>{index === 0 && <div className="rounded-xl border border-emerald-200 bg-emerald-50 px-4 py-3"><div className="text-xs font-black uppercase tracking-wide text-emerald-700">Newest AI suggestions</div><p className="mt-1 text-xs text-emerald-900">These are the latest evidence-backed options. Your earlier suggestions remain available below.</p></div>}{index === currentRecommendationCount && <div className="mt-2 rounded-xl border border-slate-200 bg-slate-50 px-4 py-3"><div className="text-xs font-black uppercase tracking-wide text-slate-600">Previous suggestions retained</div><p className="mt-1 text-xs text-slate-500">Choose an earlier direction if it still fits better. It will use the research evidence from that suggestion.</p></div>}</div><div className={`rounded-xl border p-4 ${selectedIdea === item.title && selectedResearchRunId === item.researchRunId && !customType ? "border-brand-500 bg-brand-50 ring-2 ring-brand-100" : item.recommendationSet === "previous" ? "border-slate-200 bg-slate-50/70" : "border-slate-200 bg-white"}`}><button type="button" onClick={() => { setCustomType(""); setSelectedIdea(item.title); setSelectedResearchRunId(item.researchRunId ?? null); }} className="w-full text-left"><div className="flex flex-wrap items-start justify-between gap-2"><div><span className={`text-xs font-bold uppercase tracking-wide ${item.recommendationSet === "previous" ? "text-slate-500" : "text-brand-600"}`}>{item.recommendationSet === "previous" ? "Previous option" : index === 0 ? "Best new researched option" : `${label(item.buyerStage)} new alternative`}</span><h3 className="mt-1 text-sm font-bold text-slate-950">{item.title}</h3></div><div className="flex gap-2"><span className="rounded-full bg-slate-100 px-2 py-1 text-xs font-bold text-slate-600">{item.type}</span><span className="rounded-full bg-emerald-100 px-2 py-1 text-xs font-bold text-emerald-700">{item.score}% fit</span></div></div><p className="mt-2 text-xs leading-5 text-slate-600"><b>Research signal:</b> {item.signal}</p>{item.newKeywordAngle && <p className="mt-1 text-xs leading-5 text-violet-700"><b>New keyword angle:</b> {item.newKeywordAngle}</p>}{item.differenceFromPrevious && <p className="mt-1 text-xs leading-5 text-brand-700"><b>What changed:</b> {item.differenceFromPrevious}</p>}<p className="mt-1 text-xs leading-5 text-slate-600"><b>Why this fits:</b> {item.why}</p><div className="mt-2 text-xs font-bold text-emerald-700">{item.estimatedImpact.label} <span className="font-medium text-slate-400">· {label(item.estimatedImpact.confidence)}</span></div></button><details className="mt-2 text-xs text-slate-500"><summary className="cursor-pointer font-bold text-brand-700">Evidence and reasoning</summary><div className="mt-2 space-y-1">{item.evidence.map((evidence) => <div key={evidence}>• {evidence}</div>)}</div><p className="mt-2 italic">{item.estimatedImpact.disclaimer}</p></details><button type="button" onClick={() => startSetup(item, 2)} disabled={Boolean(busy)} className="mt-3 rounded-lg bg-slate-950 px-4 py-2 text-xs font-bold text-white disabled:opacity-50">Select option and continue →</button></div></Fragment>)}</div>
          <div className="mt-4 rounded-xl border border-slate-200 bg-white p-4">
            <label className="block"><span className="text-xs font-bold text-slate-600">Choose another supported format</span><select value={customType} onChange={(event) => { const value = event.target.value; setCustomType(value); setTargetWordCount(""); setSelectedIdea(value ? `Create a project-specific ${value} using the completed lead-magnet research and the strongest conversion angle.` : recommendations[0]?.title ?? ""); setSelectedResearchRunId(value ? null : recommendations[0]?.researchRunId ?? null); }} className="mt-1 w-full rounded-lg border border-slate-300 bg-white px-3 py-2 text-sm"><option value="">Use one of the AI recommendations above</option>{supportedTypes.map((item) => <option key={item}>{item}</option>)}</select></label>
            {customType && <div className="mt-4 rounded-xl border border-brand-200 bg-brand-50 p-4"><label className="block"><span className="text-xs font-bold text-brand-900">Target number of words for {customType} *</span><input autoFocus type="number" min={250} max={10000} step={250} required value={targetWordCount} onChange={(event) => setTargetWordCount(event.target.value)} placeholder="Example: 1500" className="mt-1 w-full rounded-lg border border-brand-300 bg-white px-3 py-2 text-sm outline-none focus:border-brand-600" /><span className="mt-1 block text-xs leading-5 text-brand-800">AI will generate within approximately 10% of this target. Choose 250–10,000 words.</span></label><div className="mt-3 flex flex-wrap gap-2">{[1000, 1500, 2000, 3000].map((words) => <button key={words} type="button" onClick={() => setTargetWordCount(String(words))} className={`rounded-lg border px-3 py-1.5 text-xs font-bold ${targetWordCount === String(words) ? "border-brand-600 bg-brand-600 text-white" : "border-brand-200 bg-white text-brand-700"}`}>{words.toLocaleString()} words</button>)}</div><button type="button" onClick={() => startSetup(undefined, 2)} disabled={Boolean(busy) || !hasValidTargetWordCount} className="mt-4 rounded-lg bg-slate-950 px-4 py-2 text-xs font-bold text-white disabled:cursor-not-allowed disabled:opacity-50">Continue with {customType} →</button></div>}
          </div>
        </section>}
      </div>}
    </section>}

    {setupStep === 0 && leadMagnets.length > 1 && !data.capabilities.clientViewer && <section className="rounded-2xl border border-slate-200 bg-white p-5 shadow-sm">
      <div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between"><div><div className="text-xs font-bold uppercase tracking-wide text-brand-600">Project lead magnets</div><h2 className="mt-1 text-lg font-bold text-slate-950">Choose a lead magnet to manage</h2><p className="mt-1 text-sm text-slate-500">Every lead magnet is independent and keeps its own version history, approval, publishing, and performance.</p></div>{data.capabilities.canGenerate && <button type="button" onClick={startNewLeadMagnet} className="w-fit rounded-lg bg-slate-950 px-4 py-2.5 text-sm font-bold text-white">+ Create another lead magnet</button>}</div>
      <div className="mt-4 grid gap-3 md:grid-cols-2 xl:grid-cols-3">{leadMagnets.map((item) => <button key={item.seriesId} type="button" onClick={() => openLeadMagnet(item)} className={`rounded-xl border p-4 text-left transition ${funnel?.seriesId === item.seriesId ? "border-brand-500 bg-brand-50 ring-2 ring-brand-100" : "border-slate-200 hover:border-brand-200 hover:bg-slate-50"}`}><div className="flex items-start justify-between gap-3"><div className="min-w-0"><div className="truncate text-sm font-bold text-slate-950">{item.title}</div><div className="mt-1 text-xs text-slate-500">{label(item.magnetType)} · v{item.version}</div></div><span className={`shrink-0 rounded-full px-2 py-1 text-xs font-bold ${statusTone(item.status)}`}>{label(item.status)}</span></div><div className="mt-3 text-xs font-bold text-brand-700">Open results →</div></button>)}</div>
    </section>}

    {setupStep > 0 ? null : !funnel ? <section className="rounded-2xl border border-dashed border-brand-300 bg-brand-50/50 p-10 text-center"><div className="text-xs font-bold uppercase tracking-wide text-brand-600">No lead magnets yet</div><h2 className="mt-2 text-xl font-bold text-slate-950">Create your first lead magnet</h2><p className="mx-auto mt-2 max-w-2xl text-sm leading-6 text-slate-600">AI will research the project, recommend the best opportunity, show the evidence, and let you refine the setup before generating the complete funnel.</p>{data.capabilities.canGenerate && <button type="button" onClick={startNewLeadMagnet} className="mt-5 rounded-lg bg-slate-950 px-6 py-3 text-sm font-bold text-white">Create new lead magnet</button>}</section> : <>
      <div id="lead-magnet-results" className="flex scroll-mt-6 flex-col gap-3 rounded-xl border border-slate-200 bg-white px-4 py-3 lg:flex-row lg:items-center lg:justify-between">
        <div className="flex min-w-0 items-center gap-3"><div className="min-w-0"><h2 className="truncate text-lg font-bold text-slate-950">{funnel.title}</h2><p className="text-xs text-slate-500">{label(funnel.magnetType)} · Approved {date(funnel.approvedAt)} · Published {date(funnel.publishedAt)}</p></div></div>
        <div className="flex flex-wrap gap-2">{data.capabilities.canGenerate && <><button onClick={startNewLeadMagnet} disabled={Boolean(busy)} className="rounded-lg bg-slate-950 px-3 py-2 text-sm font-bold text-white">+ New lead magnet</button><button onClick={refineLeadMagnet} disabled={Boolean(busy)} className="rounded-lg border border-brand-200 px-3 py-2 text-sm font-bold text-brand-700">Edit setup</button></>}{data.capabilities.canApprove && !["approved", "published"].includes(funnel.status) && <button onClick={approve} disabled={Boolean(busy)} className="rounded-lg bg-brand-600 px-3 py-2 text-sm font-bold text-white">Approve exact version</button>}{["approved", "published"].includes(funnel.status) && <button type="button" onClick={openWebsiteHandoff} disabled={Boolean(busy) || Boolean(activeWebsiteJob) || !data.websiteHandoff.siteArchitectReady} className="rounded-lg bg-cyan-700 px-3 py-2 text-sm font-bold text-white disabled:bg-slate-300">{activeWebsiteJob ? `Website generation ${activeWebsiteJob.progress}%` : websiteHandoffPageId ? "Update Landing Page →" : "Connect to Landing Page →"}</button>}{data.capabilities.canPublish && funnel.status === "approved" && (connectedRegistrationForm ? <button onClick={publish} disabled={Boolean(busy)} className="rounded-lg bg-emerald-600 px-3 py-2 text-sm font-bold text-white">{busy === "publish" ? "Validating…" : "Validate & publish"}</button> : <button onClick={openEmailSetup} disabled={Boolean(busy)} className="rounded-lg border border-amber-300 bg-amber-50 px-3 py-2 text-sm font-bold text-amber-900">Set up registration →</button>)}{funnel.publicUrl && <a href={funnel.publicUrl} target="_blank" rel="noreferrer" className="rounded-lg border border-brand-200 px-3 py-2 text-sm font-bold text-brand-700">Open live funnel ↗</a>}</div>
      </div>
      <div className="overflow-x-auto border-b border-slate-200"><div className="flex min-w-max gap-1">{visibleTabs.map((item) => <button key={item} onClick={() => setTab(item)} className={`border-b-2 px-4 py-3 text-sm font-bold ${tab === item ? "border-brand-600 text-brand-700" : "border-transparent text-slate-500 hover:text-slate-800"}`}>{item}</button>)}</div></div>

      {tab === "Funnel assets" && <div className="grid gap-5 xl:grid-cols-[1.2fr_.8fr]">
        <Panel title="Lead magnet" eyebrow={label(funnel.magnetType)}>{typeof funnel.assetJson.coverImage === "string" && funnel.assetJson.coverImage.startsWith("data:image/") && <img src={funnel.assetJson.coverImage} alt={`${funnel.title} branded cover`} className="mb-5 aspect-[1200/630] w-full rounded-2xl border border-slate-200 object-cover" />}<h3 className="text-xl font-bold text-slate-950">{text(funnel.assetJson.title, funnel.title)}</h3><p className="mt-2 text-sm leading-6 text-slate-600">{text(funnel.assetJson.promise)}</p>{typeof funnel.assetJson.generatedWordCount === "number" && <div className="mt-3 flex flex-wrap gap-2 text-xs font-bold"><span className="rounded-full bg-slate-100 px-3 py-1.5 text-slate-700">{funnel.assetJson.generatedWordCount.toLocaleString()} generated words</span>{typeof funnel.assetJson.targetWordCount === "number" && <span className="rounded-full bg-brand-50 px-3 py-1.5 text-brand-700">{funnel.assetJson.targetWordCount.toLocaleString()}-word target</span>}</div>}<Rows title="What it contains" values={list(funnel.assetJson.outline)} /><div className="mt-5 space-y-4">{list(funnel.assetJson.sections).map((raw, index) => { const section = object(raw); return <div key={index} className="rounded-xl border border-slate-200 p-4"><div className="font-bold text-slate-900">{text(section.title, `Section ${index + 1}`)}</div>{typeof section.summary === "string" && <p className="mt-2 text-sm font-semibold leading-6 text-slate-600">{section.summary}</p>}{list(section.paragraphs).map((paragraph, paragraphIndex) => <p key={paragraphIndex} className="mt-2 text-sm leading-6 text-slate-600">{String(paragraph)}</p>)}<Rows values={list(section.bullets)} />{typeof section.actionStep === "string" && section.actionStep && <div className="mt-3 rounded-lg border-l-4 border-emerald-500 bg-emerald-50 px-3 py-2 text-sm text-emerald-900"><b>Action step:</b> {section.actionStep}</div>}</div>; })}</div></Panel>
        <div className="space-y-5"><Panel title="Business understanding" eyebrow="Evidence before generation">{(() => { const analysis = object(funnel.assetJson.businessAnalysis); return <><Info label="Business" value={text(analysis.business)} /><Info label="Audience" value={text(analysis.audience, funnel.audience || "Not provided")} /><Info label="Offer" value={text(analysis.offer)} /><Info label="Goal" value={text(analysis.goal, funnel.primaryGoal || "Not provided")} /><Info label="Buyer stage" value={text(analysis.buyerStage)} /><Info label="Lead-capture gap" value={text(analysis.leadCaptureGap)} /><Rows title="Evidence used" values={list(analysis.evidence).length ? list(analysis.evidence) : list(funnel.assetJson.opportunityEvidence)} /><Rows title="Assumptions" values={list(analysis.assumptions)} /></>; })()}</Panel><Panel title="Brand and generated visuals">{(() => { const brand = object(funnel.assetJson.branding); const generatedImages = list(funnel.assetJson.generatedImages).map(object); return <><Info label="Business name" value={text(brand.businessName)} /><Info label="Brand voice" value={text(brand.brandVoice, funnel.brandVoice || "Not provided")} /><Info label="Visual style" value={text(brand.visualStyle)} /><div className="mt-4 grid gap-3">{generatedImages.map((image, index) => typeof image.dataUrl === "string" && image.dataUrl.startsWith("data:image/") ? <figure key={index} className="overflow-hidden rounded-xl border border-slate-200 bg-white"><img src={image.dataUrl} alt={text(image.altText, `Supporting visual ${index + 1}`)} className="w-full" /><figcaption className="border-t border-slate-100 px-3 py-2 text-xs text-slate-500"><div>{text(image.placement, text(image.role))}</div><div className="mt-1 font-semibold text-slate-700">Evidence source: {typeof image.sourceUrl === "string" && image.sourceUrl.startsWith("https://") ? <a href={image.sourceUrl} target="_blank" rel="noreferrer" className="text-brand-700 underline">{text(image.sourceLabel, image.sourceUrl)}</a> : text(image.sourceLabel, "Source required before publishing")}</div>{typeof image.attribution === "string" && image.attribution && <div className="mt-1 font-semibold text-slate-500">{image.attribution}</div>}{typeof image.sourceNote === "string" && image.sourceNote && <div className="mt-1 leading-5">{image.sourceNote}</div>}</figcaption></figure> : null)}</div><Rows title="Visual rationale" values={list(funnel.assetJson.imagePlan).map((item) => text(object(item).altText, text(object(item).role)))} /></>; })()}</Panel><Panel title="Why this funnel"><p className="text-sm leading-6 text-slate-600">{funnel.recommendationReason}</p><Info label="Audience" value={funnel.audience} /><Info label="Primary goal" value={funnel.primaryGoal} /><Info label="Brand voice" value={funnel.brandVoice} /></Panel><Panel title="A/B test plan"><div className="space-y-3">{funnel.abTestsJson.map((raw, index) => { const item = object(raw); return <div key={index} className="rounded-xl border border-violet-100 bg-violet-50 p-3"><div className="text-xs font-bold uppercase text-violet-700">{text(item.element, "Test")}</div><div className="mt-1 text-sm font-bold text-slate-900">{text(item.variation)}</div><p className="mt-1 text-xs leading-5 text-slate-600">{text(item.hypothesis)}</p></div>; })}</div></Panel></div>
      </div>}
      {tab === "Landing & form" && <div className="grid gap-5 xl:grid-cols-[1.2fr_.8fr]"><Panel title="Landing page preview" eyebrow={funnel.landingPageJson.contentMode === "full_content" ? "Full promotional content + registration" : "Sales pitch + registration"}><div className="rounded-2xl bg-slate-950 px-6 py-10 text-center text-white"><div className="mx-auto max-w-2xl"><h3 className="text-3xl font-bold leading-tight">{text(funnel.landingPageJson.headline)}</h3><p className="mx-auto mt-3 max-w-xl text-sm leading-6 text-slate-300">{text(funnel.landingPageJson.subheadline)}</p><div className="mx-auto mt-6 grid max-w-xl gap-2 text-left">{list(funnel.landingPageJson.benefitBullets).map((item) => <div key={String(item)} className="rounded-lg bg-white/10 px-3 py-2 text-sm">✓ {String(item)}</div>)}</div></div></div><Rows title="Proof and objections" values={list(funnel.landingPageJson.proofBlocks).map((item) => typeof item === "string" ? item : text(object(item).title, text(object(item).description)))} /><LandingContentDetails funnel={funnel} /></Panel><Panel title="Opt-in form"><div className="space-y-3">{list(funnel.optInFormJson.fields).map((raw, index) => { const field = object(raw); return <label key={index} className="block"><span className="text-xs font-bold text-slate-600">{text(field.label, "Field")}{field.required ? " *" : ""}</span><input disabled placeholder={text(field.label, "Field")} className="mt-1 w-full rounded-lg border border-slate-300 bg-slate-50 px-3 py-2 text-sm" /></label>; })}<button disabled className="w-full rounded-lg bg-brand-600 px-4 py-2.5 text-sm font-bold text-white">{text(funnel.optInFormJson.submitLabel, "Get the resource")}</button><p className="text-xs leading-5 text-slate-500">{text(funnel.optInFormJson.consentText)}</p></div><div className="mt-5 border-t border-slate-100 pt-4"><Info label="SEO title" value={text(funnel.seoMetadataJson.title)} /><Info label="Meta description" value={text(funnel.seoMetadataJson.description)} /></div></Panel></div>}
      {tab === "Email sequence" && <div className="grid gap-5 xl:grid-cols-[.8fr_1.2fr]"><div className="space-y-5"><Panel title="Thank-you page"><Info label="Headline" value={text(funnel.thankYouPageJson.headline)} /><p className="text-sm leading-6 text-slate-600">{text(funnel.thankYouPageJson.body)}</p><Info label="Next step" value={text(funnel.thankYouPageJson.nextStepCta)} /></Panel><Panel title="Delivery email"><Info label="Subject" value={text(funnel.deliveryEmailJson.subject)} /><Info label="Preview" value={text(funnel.deliveryEmailJson.previewText)} /><p className="whitespace-pre-wrap text-sm leading-6 text-slate-600">{text(funnel.deliveryEmailJson.body)}</p></Panel></div><Panel title="Follow-up sequence" eyebrow={`${funnel.followUpSequenceJson.length} planned emails`}><div className="space-y-3">{funnel.followUpSequenceJson.map((raw, index) => { const item = object(raw); return <div key={index} className="grid gap-3 rounded-xl border border-slate-200 p-4 sm:grid-cols-[80px_minmax(0,1fr)]"><div className="text-sm font-bold text-brand-700">{text(item.day, `Email ${index + 1}`)}</div><div><div className="font-bold text-slate-900">{text(item.subject)}</div><div className="mt-1 text-xs font-semibold text-slate-500">Goal: {text(item.goal)}</div><p className="mt-2 whitespace-pre-wrap text-sm leading-6 text-slate-600">{text(item.body)}</p></div></div>; })}</div></Panel></div>}
      {tab === "Export & handoff" && <div className="grid gap-5 lg:grid-cols-2 xl:grid-cols-4">
        <Panel title="Connect to Landing Page" eyebrow="Site Architect handoff"><p className="text-sm leading-6 text-slate-600">Send the approved version to a reviewable Site Architect landing-page draft. This does not publish or change the live website.</p>{activeWebsiteJob && <div className="mt-3 rounded-lg border border-cyan-200 bg-cyan-50 px-3 py-3 text-xs font-semibold leading-5 text-cyan-900"><div className="flex items-center justify-between gap-3"><span>Website generation is {activeWebsiteJob.status}. The landing page will be available when it finishes.</span><span className="shrink-0 rounded-full bg-white px-2.5 py-1 font-black">{activeWebsiteJob.progress}%</span></div><div className="mt-2 h-1.5 overflow-hidden rounded-full bg-cyan-100"><div className="h-full rounded-full bg-cyan-600 transition-all" style={{ width: `${Math.max(2, activeWebsiteJob.progress)}%` }} /></div><div className="mt-2 font-normal">This status refreshes automatically. Your approved lead magnet remains saved.</div></div>}{websiteHandoffPageId ? <div className="mt-3 rounded-lg border border-emerald-200 bg-emerald-50 px-3 py-2 text-xs font-semibold text-emerald-800">Linked to {text(websiteHandoffRecord.pageTitle, "a Site Architect page")} · Version {String(websiteHandoffRecord.pageVersion || "1")}</div> : null}<div className="mt-4 flex flex-wrap gap-2"><button type="button" disabled={!["approved", "published"].includes(funnel.status) || Boolean(busy) || Boolean(activeWebsiteJob) || !data.websiteHandoff.siteArchitectReady} onClick={openWebsiteHandoff} className="rounded-lg bg-cyan-700 px-4 py-2.5 text-sm font-bold text-white disabled:bg-slate-300">{activeWebsiteJob ? "Waiting for Website Generation" : websiteHandoffPageId ? "Update Landing Page Draft" : "Connect to Landing Page"}</button>{websiteHandoffPageId ? <button type="button" onClick={() => navigate(`/site-architect?projectId=${encodeURIComponent(projectId)}&pageId=${encodeURIComponent(websiteHandoffPageId)}&step=content&manage=1&source=lead-magnet`)} className="rounded-lg border border-cyan-200 px-4 py-2.5 text-sm font-bold text-cyan-800">Open Site Architect</button> : null}</div>{!data.websiteHandoff.siteArchitectReady ? <p className="mt-3 text-xs leading-5 text-amber-700">Start the website in Site Architect before connecting this lead magnet.</p> : !["approved", "published"].includes(funnel.status) ? <p className="mt-3 text-xs leading-5 text-amber-700">Approve this exact version before connecting it to the website.</p> : !activeWebsiteJob && !connectedRegistrationForm ? <p className="mt-3 text-xs leading-5 text-amber-700">The landing-page draft can be created now. Registration and delivery will be marked as setup required until a provider form is validated.</p> : !activeWebsiteJob ? <p className="mt-3 text-xs leading-5 text-emerald-700">The validated registration form and provider delivery handoff will be included in the draft.</p> : null}</Panel>
        <Panel title="Lead magnet PDF" eyebrow="Client-ready asset"><p className="text-sm leading-6 text-slate-600">Download the complete branded lead magnet for review, handoff, manual delivery, or use outside the connected funnel.</p><button type="button" onClick={() => downloadExport("pdf")} className="mt-4 inline-flex rounded-lg bg-slate-950 px-4 py-2.5 text-sm font-bold text-white">Download PDF</button></Panel>
        <Panel title="Complete landing-page HTML" eyebrow="Portable webpage"><p className="text-sm leading-6 text-slate-600">Download one responsive HTML file containing the page design, approved image, form, thank-you state, SEO metadata, and secure delivery connection.</p><button type="button" onClick={() => downloadExport("landing-html")} className="mt-4 rounded-lg bg-indigo-700 px-4 py-2.5 text-sm font-bold text-white">Download Complete HTML</button>{!funnel.publicUrl && <p className="mt-3 text-xs leading-5 text-amber-700">The HTML is preview-only until this funnel is activated.</p>}</Panel>
        <Panel title="Email sequence files" eyebrow="Portable copy"><p className="text-sm leading-6 text-slate-600">Use plain text for easy copying into any provider, or HTML for a formatted review and implementation file.</p><div className="mt-4 flex flex-wrap gap-2"><button type="button" onClick={() => downloadExport("email-text")} className="rounded-lg border border-brand-200 px-4 py-2.5 text-sm font-bold text-brand-700">Download TXT</button><button type="button" onClick={() => downloadExport("email-html")} className="rounded-lg bg-brand-600 px-4 py-2.5 text-sm font-bold text-white">Download HTML</button></div></Panel>
        <Panel title="Website opt-in widget" eyebrow="Preview and embed"><p className="text-sm leading-6 text-slate-600">Preview and download a responsive HTML widget containing the same validated provider registration form.</p><div className="mt-4 flex flex-wrap gap-2"><button type="button" onClick={previewWidget} className="rounded-lg border border-brand-200 px-4 py-2.5 text-sm font-bold text-brand-700">Open widget preview ↗</button><button type="button" onClick={() => downloadExport("widget")} className="rounded-lg bg-emerald-600 px-4 py-2.5 text-sm font-bold text-white">Download widget</button></div>{!funnel.publicUrl && <p className="mt-3 text-xs leading-5 text-amber-700">Approve the funnel, validate the provider form, and publish before downloading the final widget.</p>}</Panel>
        <div className="lg:col-span-2 xl:col-span-4"><Panel title="Provider delivery handoff" eyebrow="V1 provider embed"><p className="text-sm leading-6 text-slate-600">Paste your email or CRM provider’s official form embed in Integration. The provider stores registrations and runs its own confirmation and follow-up automation. Export the generated email sequence here when you need to copy it into that provider.</p></Panel></div>
      </div>}
      {tab === "Integration" && <div id="lead-magnet-email-setup" className="grid scroll-mt-6 gap-5 xl:grid-cols-[.9fr_1.1fr]">
        <div className="xl:col-span-2"><Panel title="Add the provider registration form" eyebrow="Three steps before publishing"><ol className="grid gap-3 md:grid-cols-3"><li className="rounded-xl border border-slate-200 bg-slate-50 p-4"><div className="text-xs font-black text-brand-700">1 · Build the form</div><p className="mt-2 text-sm leading-6 text-slate-600">In your preferred email or CRM provider, create a signup form and choose the audience or list that should receive registrations.</p></li><li className="rounded-xl border border-slate-200 bg-slate-50 p-4"><div className="text-xs font-black text-brand-700">2 · Copy its embed</div><p className="mt-2 text-sm leading-6 text-slate-600">Copy the provider’s official form embed code. Do not paste an API key, password, tracking-only script, or an entire webpage.</p></li><li className="rounded-xl border border-slate-200 bg-slate-50 p-4"><div className="text-xs font-black text-brand-700">3 · Validate and publish</div><p className="mt-2 text-sm leading-6 text-slate-600">Paste and validate the form below. Then publish this funnel; the same form is included in live, HTML, and WordPress versions.</p></li></ol><div className="mt-4 rounded-xl border border-cyan-200 bg-cyan-50 px-4 py-3 text-sm leading-6 text-cyan-950"><b>V1 responsibility:</b> your provider stores the lead, records consent, and sends confirmation or follow-up emails. Configure that automation inside the provider, using the generated email sequence available in Export &amp; handoff.</div></Panel></div>
        <Panel title="Provider form embed" eyebrow="Validated before publish">
          <Field label="Provider name (for example Mailchimp or Brevo)" value={providerName} onChange={setProviderName} />
          <label className="mt-3 block text-xs font-bold text-slate-600">Official form embed code<textarea value={providerEmbedCode} onChange={(event) => setProviderEmbedCode(event.target.value)} disabled={!data.capabilities.canManageIntegration} rows={12} placeholder={'<form action="https://…">…</form> or <script src="https://…"></script>'} className="mt-1 w-full rounded-lg border border-slate-300 px-3 py-2 font-mono text-xs leading-5" /></label>
          {data.capabilities.canManageIntegration && <button onClick={connect} disabled={Boolean(busy) || providerName.trim().length < 2 || providerEmbedCode.trim().length < 20} className="mt-4 w-full rounded-lg bg-brand-600 px-4 py-2.5 text-sm font-bold text-white disabled:bg-slate-300">{busy === "connect" ? "Validating…" : "Validate & save form"}</button>}
          <p className="mt-3 text-xs leading-5 text-slate-500">The embed is encrypted at rest, never executed inside the SEnuke admin screen, and rendered in a restricted iframe on published pages. SEnuke does not receive your provider password or API key.</p>
        </Panel>
        <Panel title="Publish readiness" eyebrow={funnel.validationJson.valid ? "Passed" : connectedRegistrationForm ? "Provider form ready" : "One action required"}>
          <p className="text-sm leading-6 text-slate-600">{funnel.validationJson.valid ? "This approved funnel passed its content, provider-form, download, and publishing checks." : connectedRegistrationForm ? `${connectedRegistrationForm.listName || "The provider"} registration form was validated ${date(connectedRegistrationForm.lastVerifiedAt)}. Publish the approved funnel when ready.` : "Add and validate the provider registration form on the left before publishing."}</p>
          {connectedRegistrationForm?.errorMessage && <p className="mt-3 rounded-lg bg-rose-50 px-3 py-2 text-xs font-semibold text-rose-700">{connectedRegistrationForm.errorMessage}</p>}
          {list(funnel.validationJson.errors).filter((error) => !/(Connect and verify an email service|Add and validate a provider registration form)/i.test(String(error))).length > 0 && <Rows title="Other blocking findings" values={list(funnel.validationJson.errors).filter((error) => !/(Connect and verify an email service|Add and validate a provider registration form)/i.test(String(error)))} />}
          {connectedRegistrationForm && funnel.status === "approved" && <button type="button" onClick={publish} disabled={Boolean(busy)} className="mt-4 rounded-lg bg-emerald-600 px-4 py-2.5 text-sm font-bold text-white">{busy === "publish" ? "Validating…" : "Validate & publish"}</button>}
        </Panel>
      </div>}
      {tab === "Performance" && <div className="space-y-5">{performanceAvailable ? <><div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-6"><Metric label="Views" value={funnel.performance.views} /><Metric label="Opt-ins" value={funnel.performance.optIns} /><Metric label="Conversion" value={`${funnel.performance.conversionRate}%`} /><Metric label="Downloads" value={funnel.performance.downloads} /><Metric label="Open rate" value={`${funnel.performance.openRate}%`} /><Metric label="Click rate" value={`${funnel.performance.clickRate}%`} /></div><Panel title="AI optimization recommendations"><div className="space-y-3">{funnel.optimizationRecommendations.map((item) => <div key={item.title} className="rounded-xl border border-slate-200 p-4"><div className="flex items-center gap-2"><span className={`rounded-full px-2 py-1 text-xs font-bold ${item.priority === "high" ? "bg-rose-100 text-rose-700" : item.priority === "medium" ? "bg-amber-100 text-amber-700" : "bg-slate-100 text-slate-700"}`}>{label(item.priority)}</span><span className="font-bold text-slate-900">{item.title}</span></div><p className="mt-2 text-sm leading-6 text-slate-600">{item.why}</p><p className="mt-2 text-sm font-semibold text-brand-700">Next test: {item.action}</p></div>)}</div></Panel></> : <Panel title="Measurement is not available yet" eyebrow="No verified performance evidence"><p className="text-sm leading-6 text-slate-600">This lead magnet has no recorded views, registrations, downloads, email opens, or clicks. SEnuke is not showing manufactured zero-performance conclusions.</p><p className="mt-3 text-sm font-semibold text-slate-800">Publish with tracking, or import a verified performance snapshot below. Optimization recommendations will appear after evidence exists.</p></Panel>}{data.capabilities.canEdit && <Panel title="Import performance snapshot" eyebrow="For integrations not yet sending events"><div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-3">{Object.entries(metrics).map(([key, value]) => <Field key={key} label={label(key)} value={value} onChange={(next) => setMetrics((current) => ({ ...current, [key]: next }))} numeric />)}</div><button onClick={saveMetrics} disabled={Boolean(busy)} className="mt-4 rounded-lg bg-brand-600 px-4 py-2.5 text-sm font-bold text-white">Save verified snapshot</button></Panel>}</div>}
      {tab === "History" && <div className="grid gap-5 xl:grid-cols-[.8fr_1.2fr]"><div className="space-y-5"><Panel title="Lead magnets in this project"><div className="space-y-2">{leadMagnets.map((item) => <button key={item.seriesId} onClick={() => setActiveId(item.id)} className={`flex w-full items-center justify-between rounded-xl border px-4 py-3 text-left ${item.seriesId === funnel.seriesId ? "border-brand-500 bg-brand-50" : "border-slate-200"}`}><div className="min-w-0"><div className="truncate font-bold text-slate-900">{item.title}</div><div className="mt-1 text-xs text-slate-500">{label(item.magnetType)} · latest v{item.version}</div></div><span className={`ml-2 shrink-0 rounded-full px-2 py-1 text-xs font-bold ${statusTone(item.status)}`}>{label(item.status)}</span></button>)}</div></Panel><Panel title="Versions of selected lead magnet"><div className="space-y-2">{selectedVersions.map((item) => <button key={item.id} onClick={() => setActiveId(item.id)} className={`flex w-full items-center justify-between rounded-xl border px-4 py-3 text-left ${item.id === funnel.id ? "border-brand-500 bg-brand-50" : "border-slate-200"}`}><div><div className="font-bold text-slate-900">Version {item.version}</div><div className="mt-1 text-xs text-slate-500">{item.title}</div></div><span className={`rounded-full px-2 py-1 text-xs font-bold ${statusTone(item.status)}`}>{label(item.status)}</span></button>)}</div></Panel></div><div className="space-y-5"><Panel title="Approval history"><div className="relative space-y-4 before:absolute before:bottom-2 before:left-[11px] before:top-2 before:w-px before:bg-slate-200">{funnel.decisions.map((item) => <div key={item.id} className="relative grid grid-cols-[24px_minmax(0,1fr)] gap-3"><span className="z-10 mt-1 h-6 w-6 rounded-full border-4 border-white bg-brand-500" /><div><div className="font-bold text-slate-900">{label(item.decision)}</div><div className="text-xs text-slate-500">{date(item.createdAt)}</div>{item.comments && <p className="mt-1 text-sm leading-6 text-slate-600">{item.comments}</p>}</div></div>)}</div></Panel><Panel title="Complete activity log"><div className="space-y-3">{data.activities.length ? data.activities.map((item) => <div key={item.id} className="rounded-xl border border-slate-200 px-4 py-3"><div className="font-bold text-slate-900">{label(item.action.replace(/^lead_magnet\./, ""))}</div><div className="mt-1 text-xs text-slate-500">{date(item.createdAt)} · {item.actor?.name || item.actor?.email || "System"}</div></div>) : <p className="text-sm text-slate-500">No funnel activity has been recorded.</p>}</div></Panel></div></div>}
    </>}
    {websiteHandoffOpen && funnel && <div className="fixed inset-0 z-[140] grid place-items-center bg-slate-950/65 p-4" role="dialog" aria-modal="true" aria-labelledby="lead-magnet-website-handoff-title"><button type="button" className="absolute inset-0" aria-label="Close website handoff" disabled={busy === "website-handoff"} onClick={() => setWebsiteHandoffOpen(false)} /><div className="relative flex max-h-[92vh] w-full max-w-2xl flex-col overflow-hidden rounded-2xl bg-white shadow-2xl"><div className="border-b bg-gradient-to-r from-cyan-50 via-white to-indigo-50 px-6 py-5"><div className="flex items-start justify-between gap-4"><div><div className="text-xs font-black uppercase tracking-wide text-cyan-700">Lead Magnets → Site Architect</div><h2 id="lead-magnet-website-handoff-title" className="mt-1 text-xl font-black text-slate-950">Add the complete landing page to your website</h2><p className="mt-1 text-sm leading-6 text-slate-500">This creates a reviewable Site Architect version. It does not change the live website until website Quality, Approval, and Publish are completed.</p></div><button type="button" disabled={busy === "website-handoff"} onClick={() => setWebsiteHandoffOpen(false)} className="grid h-9 w-9 shrink-0 place-items-center rounded-lg border bg-white text-lg text-slate-500">×</button></div></div><div className="min-h-0 flex-1 overflow-y-auto p-6"><div className="grid gap-4 sm:grid-cols-2"><label className="text-xs font-black text-slate-700 sm:col-span-2">Page title<input value={websiteHandoff.title} onChange={(event) => setWebsiteHandoff((current) => ({ ...current, title: event.target.value }))} maxLength={255} className="mt-1.5 w-full rounded-lg border border-slate-300 p-2.5 text-sm font-normal" /></label><label className="text-xs font-black text-slate-700">URL slug<input value={websiteHandoff.slug} onChange={(event) => setWebsiteHandoff((current) => ({ ...current, slug: event.target.value.toLowerCase().replace(/[^a-z0-9-]+/g, "-").replace(/^-|-$/g, "") }))} maxLength={180} className="mt-1.5 w-full rounded-lg border border-slate-300 p-2.5 text-sm font-normal" /></label><label className="text-xs font-black text-slate-700">Primary CTA<input value={websiteHandoff.targetCta} onChange={(event) => setWebsiteHandoff((current) => ({ ...current, targetCta: event.target.value }))} maxLength={40} className="mt-1.5 w-full rounded-lg border border-slate-300 p-2.5 text-sm font-normal" /></label><label className="text-xs font-black text-slate-700 sm:col-span-2">Primary keyword<input value={websiteHandoff.primaryKeyword} onChange={(event) => setWebsiteHandoff((current) => ({ ...current, primaryKeyword: event.target.value }))} maxLength={255} className="mt-1.5 w-full rounded-lg border border-slate-300 p-2.5 text-sm font-normal" /></label><label className="flex items-start gap-3 rounded-xl border border-slate-200 bg-slate-50 p-4 text-sm font-semibold text-slate-700 sm:col-span-2"><input type="checkbox" checked={websiteHandoff.includeInNavigation} onChange={(event) => setWebsiteHandoff((current) => ({ ...current, includeInNavigation: event.target.checked }))} className="mt-1" /><span>Add this campaign page to the primary navigation. Leave this off when traffic will arrive through campaigns, email, social posts, or contextual links.</span></label></div><div className="mt-5 rounded-xl border border-emerald-200 bg-emerald-50 p-4"><div className="text-xs font-black uppercase tracking-wide text-emerald-700">The website draft will include</div><p className="mt-1 text-sm leading-6 text-emerald-950">Approved landing copy, lead-magnet image, benefits, proof, thank-you message, CTA, SEO metadata, and a two-way link to this funnel. {connectedRegistrationForm ? "The validated provider registration form and delivery handoff will also be included." : "Registration and delivery will be marked as setup required; complete them before website publishing."}</p></div></div><div className="flex flex-wrap items-center justify-between gap-3 border-t bg-slate-50 px-6 py-4"><p className="text-xs text-slate-500">{websiteHandoffRecord.pageId ? "The linked page receives a new review version; its current live version remains unchanged." : "A new landing-page draft will be added to Page Management."}</p><div className="flex gap-2"><button type="button" disabled={busy === "website-handoff"} onClick={() => setWebsiteHandoffOpen(false)} className="rounded-lg border bg-white px-4 py-2.5 text-sm font-bold">Cancel</button><button type="button" disabled={busy === "website-handoff" || websiteHandoff.title.trim().length < 2 || websiteHandoff.slug.trim().length < 1 || websiteHandoff.primaryKeyword.trim().length < 2 || websiteHandoff.targetCta.trim().length < 2} onClick={() => void handoffToWebsite()} className="rounded-lg bg-cyan-700 px-5 py-2.5 text-sm font-black text-white disabled:bg-slate-300">{busy === "website-handoff" ? "Creating website draft…" : websiteHandoffRecord.pageId ? "Create Updated Website Draft" : "Create Website Draft"}</button></div></div></div></div>}
  </div>;
}

function Panel({ title, eyebrow, children }: { title: string; eyebrow?: string; children: ReactNode }) { return <section className="rounded-2xl border border-slate-200 bg-white p-5 shadow-sm">{eyebrow && <div className="text-xs font-bold uppercase tracking-wide text-brand-600">{eyebrow}</div>}<h2 className={eyebrow ? "mt-1 text-lg font-bold text-slate-950" : "text-lg font-bold text-slate-950"}>{title}</h2><div className="mt-4">{children}</div></section>; }
function LeadMagnetPageLoading() { return <section className="rounded-2xl border border-slate-200 bg-white p-6 shadow-sm" aria-live="polite"><div className="flex items-center gap-3"><span className="h-5 w-5 animate-spin rounded-full border-2 border-slate-200 border-t-brand-600" aria-hidden="true" /><div><h2 className="text-sm font-bold text-slate-900">Opening Lead Magnets</h2><p className="mt-0.5 text-xs text-slate-500">Loading the saved funnels for this project. No AI work is running.</p></div></div></section>; }
function LandingContentDetails({ funnel }: { funnel: Funnel }) {
  const fullContent = funnel.landingPageJson.contentMode === "full_content";
  const assetSections = list(funnel.assetJson.sections).map(object);
  const previewSections = fullContent ? assetSections : assetSections.slice(0, 4);
  const faqs = list(funnel.landingPageJson.faqs).map(object);
  return <div className="mt-6 space-y-5 border-t border-slate-100 pt-5"><div><div className="text-xs font-bold uppercase tracking-wide text-slate-400">{fullContent ? "Complete page content" : "Content preview"}</div><div className="mt-3 space-y-3">{previewSections.map((section, index) => <article key={index} className="rounded-xl border border-slate-200 bg-slate-50 p-4"><h3 className="font-bold text-slate-950">{text(section.title, `Section ${index + 1}`)}</h3>{typeof section.summary === "string" && <p className="mt-2 text-sm font-semibold leading-6 text-slate-600">{section.summary}</p>}{fullContent && list(section.paragraphs).map((paragraph, paragraphIndex) => <p key={paragraphIndex} className="mt-2 text-sm leading-6 text-slate-600">{String(paragraph)}</p>)}{fullContent && <Rows values={list(section.bullets)} />}{fullContent && typeof section.actionStep === "string" && section.actionStep && <div className="mt-3 rounded-lg border-l-4 border-emerald-500 bg-emerald-50 px-3 py-2 text-sm text-emerald-900"><b>Action step:</b> {section.actionStep}</div>}</article>)}</div></div>{faqs.length > 0 && <div><div className="text-xs font-bold uppercase tracking-wide text-slate-400">Frequently asked questions</div><div className="mt-3 space-y-2">{faqs.map((faq, index) => <details key={index} className="rounded-lg border border-slate-200 p-3"><summary className="cursor-pointer text-sm font-bold text-slate-900">{text(faq.question, `Question ${index + 1}`)}</summary><p className="mt-2 text-sm leading-6 text-slate-600">{text(faq.answer)}</p></details>)}</div></div>}</div>;
}
function LeadMagnetCookingScreen({ refreshing = false }: { refreshing?: boolean }) { return <AiPlanningScreen eyebrow="Lead magnet research in progress" title={refreshing ? "Hang tight — we’re refreshing your suggestions!" : "Hang tight — we’re finding your strongest lead magnet!"} description="SEnuke AI - AI Growth Operating System is reviewing Business Intake, keywords, geography, Site Analysis, the selected Opportunity, approved Strategy, and Website Plan to find the strongest lead-capture options." steps={[{ title: "Review the evidence", detail: "Business, audience, offer, approved direction, search demand, and available website evidence" }, { title: "Find the conversion gap", detail: "Buyer stage, unanswered need, website coverage, geography, and the desired customer action" }, { title: "Rank the suggestions", detail: "Format fit, usefulness, differentiation, expected outcome, confidence, and effort" }]} checks={["Ground suggestions in project evidence", "Match the buyer journey", "Keep every option editable"]} status={refreshing ? "Generating different evidence-backed alternatives…" : "Generating evidence-backed lead magnet suggestions…"} note="You will select and configure a suggestion before SEnuke AI - AI Growth Operating System creates the complete funnel." ariaLabel={refreshing ? "Refreshing lead magnet research" : "Creating lead magnet suggestions"} />; }
function LeadFunnelGenerationCookingScreen() { return <AiPlanningScreen eyebrow="Lead funnel creation in progress" title="Hang tight — we’re creating your lead magnet!" description="SEnuke AI - AI Growth Operating System is turning the researched opportunity and your approved setup details into a complete, review-ready conversion experience." steps={[{ title: "Build the lead magnet", detail: "Useful content, approved brand direction, supporting visuals, and factual safeguards" }, { title: "Create the conversion path", detail: "Landing page, opt-in form, thank-you experience, CTAs, and consent language" }, { title: "Prepare the delivery", detail: "Email sequence, integration handoff, tracking, validation, and approval checkpoints" }]} checks={["Preserve approved facts", "Keep publishing approval-gated", "Prepare measurement before launch"]} status="Creating the complete lead funnel…" note="Nothing is published automatically. You will review the asset, pages, form, and emails before approval." ariaLabel="Generating complete lead funnel with AI" />; }
function ResearchCard({ title, detail, values }: { title: string; detail: string; values: string[] }) { return <section className="rounded-xl border border-slate-200 bg-white p-4"><div className="text-xs font-bold uppercase tracking-wide text-brand-600">{title}</div><div className="mt-1 text-sm font-bold text-slate-900">{detail}</div><div className="mt-2 space-y-1">{values.length ? values.map((value, index) => <div key={index} className="truncate text-xs text-slate-500">{value}</div>) : <div className="text-xs text-slate-400">No saved evidence available.</div>}</div></section>; }
function Metric({ label, value }: { label: string; value: string | number }) { return <div className="rounded-xl border border-slate-200 bg-white p-4 shadow-sm"><div className="text-xs font-bold uppercase tracking-wide text-slate-400">{label}</div><div className="mt-2 text-2xl font-bold text-slate-950">{value}</div></div>; }
function Info({ label: itemLabel, value }: { label: string; value: string | null | undefined }) { return <div className="mt-4"><div className="text-xs font-bold uppercase tracking-wide text-slate-400">{itemLabel}</div><div className="mt-1 text-sm leading-6 text-slate-700">{value || "Not provided"}</div></div>; }
function Rows({ title, values }: { title?: string; values: unknown[] }) { return <div className="mt-4">{title && <div className="text-xs font-bold uppercase tracking-wide text-slate-400">{title}</div>}<div className="mt-2 space-y-2">{values.length ? values.map((item, index) => <div key={index} className="flex gap-2 text-sm leading-6 text-slate-700"><span className="font-bold text-emerald-600">✓</span><span>{String(item)}</span></div>) : <div className="text-sm text-slate-500">No items generated.</div>}</div></div>; }
function Field({ label: itemLabel, value, onChange, secret, numeric }: { label: string; value: string; onChange: (value: string) => void; secret?: boolean; numeric?: boolean }) { return <label className="mt-3 block"><span className="text-xs font-bold text-slate-600">{itemLabel}</span><input type={secret ? "password" : numeric ? "number" : "text"} min={numeric ? 0 : undefined} value={value} onChange={(event) => onChange(event.target.value)} className="mt-1 w-full rounded-lg border border-slate-300 px-3 py-2 text-sm outline-none focus:border-brand-500" /></label>; }
function Empty({ title, detail, compact }: { title: string; detail: string; compact?: boolean }) { return <div className={`rounded-2xl border border-dashed border-slate-300 bg-slate-50 text-center ${compact ? "p-5" : "p-10"}`}><h2 className="font-bold text-slate-950">{title}</h2><p className="mx-auto mt-2 max-w-xl text-sm leading-6 text-slate-500">{detail}</p></div>; }
